// A minimal D-Bus client for the session bus, no dependencies (src/main/dbus-mini.js).
//
// Just what kwin-bridge.js needs, and nothing more:
//   - connect to the session bus over a unix socket (path or abstract), SASL EXTERNAL
//   - call methods whose arguments and results are basic types: s o g y b i u
//   - own a bus name and serve methods with such arguments (plus Peer.Ping and Introspect)
// No signals, no match rules, no unix fds, no arrays/structs/dicts/variants in the message body:
// a message that needs them is refused (an error back to the caller), never half-parsed. Sizes
// are capped, so whatever arrives on the bus cannot make this read or allocate without bound.
//
// Spec: https://dbus.freedesktop.org/doc/dbus-specification.html (wire format, "Message Format")

const net = require('node:net');

const MAX_MESSAGE = 4 * 1024 * 1024; // the bus allows 128 MiB; Capri's messages are tens of KiB
const CALL_TIMEOUT_MS = 5000;
const TYPE = { CALL: 1, RETURN: 2, ERROR: 3, SIGNAL: 4 };
const NO_REPLY = 0x1; // NO_REPLY_EXPECTED
// header field codes -> [name, type]
const FIELDS = {
  1: ['path', 'o'], 2: ['iface', 's'], 3: ['member', 's'], 4: ['errorName', 's'],
  5: ['replySerial', 'u'], 6: ['destination', 's'], 7: ['sender', 's'], 8: ['signature', 'g'],
  9: ['unixFds', 'u'],
};
const CODE = { path: 1, iface: 2, member: 3, errorName: 4, replySerial: 5, destination: 6, signature: 8 };

// ---------- marshalling ----------

class Writer {
  constructor() {
    this.chunks = [];
    this.length = 0;
  }

  push(buf) {
    this.chunks.push(buf);
    this.length += buf.length;
  }

  align(n) {
    const pad = (n - (this.length % n)) % n;
    if (pad) this.push(Buffer.alloc(pad));
  }

  u8(v) {
    this.push(Buffer.from([v & 0xff]));
  }

  u32(v) {
    this.align(4);
    const b = Buffer.alloc(4);
    b.writeUInt32LE(v >>> 0);
    this.push(b);
  }

  i32(v) {
    this.align(4);
    const b = Buffer.alloc(4);
    b.writeInt32LE(v | 0);
    this.push(b);
  }

  str(s) {
    const d = Buffer.from(String(s), 'utf8');
    if (d.includes(0)) throw new Error('a string with a NUL byte cannot go on D-Bus');
    this.u32(d.length);
    this.push(d);
    this.push(Buffer.alloc(1));
  }

  sig(s) {
    const d = Buffer.from(String(s), 'ascii');
    this.u8(d.length);
    this.push(d);
    this.push(Buffer.alloc(1));
  }

  value(type, v) {
    switch (type) {
      case 's': case 'o': return this.str(v);
      case 'g': return this.sig(v);
      case 'y': return this.u8(v);
      case 'b': return this.u32(v ? 1 : 0);
      case 'i': return this.i32(v);
      case 'u': return this.u32(v);
      default: throw new Error(`unsupported type '${type}'`);
    }
  }

  variant(type, v) {
    this.sig(type);
    this.value(type, v);
  }

  bytes() {
    return Buffer.concat(this.chunks, this.length);
  }
}

class Reader {
  constructor(buf, le, offset = 0) {
    this.buf = buf;
    this.le = le;
    this.o = offset;
  }

  align(n) {
    this.o += (n - (this.o % n)) % n;
  }

  u8() {
    if (this.o >= this.buf.length) throw new RangeError('message truncated');
    return this.buf[this.o++];
  }

  u32() {
    this.align(4);
    const v = this.le ? this.buf.readUInt32LE(this.o) : this.buf.readUInt32BE(this.o); // throws past the end
    this.o += 4;
    return v;
  }

  i32() {
    this.align(4);
    const v = this.le ? this.buf.readInt32LE(this.o) : this.buf.readInt32BE(this.o);
    this.o += 4;
    return v;
  }

  str() {
    const n = this.u32();
    if (n > this.buf.length - this.o - 1) throw new RangeError('string past the end of the message');
    const s = this.buf.toString('utf8', this.o, this.o + n);
    this.o += n + 1;
    return s;
  }

  sig() {
    const n = this.u8();
    if (n > this.buf.length - this.o - 1) throw new RangeError('signature past the end of the message');
    const s = this.buf.toString('ascii', this.o, this.o + n);
    this.o += n + 1;
    return s;
  }

  value(type) {
    switch (type) {
      case 'y': return this.u8();
      case 'b': return this.u32() !== 0;
      case 'i': return this.i32();
      case 'u': return this.u32();
      case 's': case 'o': return this.str();
      case 'g': return this.sig();
      default: throw new Error(`unsupported type '${type}'`);
    }
  }
}

// header fields: { path, iface, member, errorName, replySerial, destination, signature }
function encode(type, flags, serial, f, body) {
  // The fields array starts at offset 16, a multiple of 8, so aligning inside its own writer
  // (offset 0) gives the same padding as in the whole message.
  const fields = new Writer();
  const put = (name, v) => {
    if (v === undefined || v === null || v === '') return;
    fields.align(8);
    fields.u8(CODE[name]);
    fields.variant(FIELDS[CODE[name]][1], v);
  };
  put('path', f.path);
  put('iface', f.iface);
  put('member', f.member);
  put('errorName', f.errorName);
  put('replySerial', f.replySerial);
  put('destination', f.destination);
  put('signature', f.signature);

  const head = new Writer();
  head.u8(0x6c); // little endian
  head.u8(type);
  head.u8(flags);
  head.u8(1); // protocol version
  head.u32(body.length);
  head.u32(serial);
  head.u32(fields.length);
  head.push(fields.bytes());
  head.align(8);
  head.push(body);
  return head.bytes();
}

// One message off the front of buf: { msg, total }, or null while it is incomplete.
function decode(buf) {
  if (buf.length < 16) return null;
  const le = buf[0] === 0x6c;
  if (!le && buf[0] !== 0x42) throw new Error('bad endianness byte');
  const rd = (o) => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const bodyLen = rd(4);
  const fieldsLen = rd(12);
  const headerEnd = 16 + fieldsLen;
  const bodyStart = headerEnd + ((8 - (headerEnd % 8)) % 8);
  const total = bodyStart + bodyLen;
  if (bodyLen > MAX_MESSAGE || fieldsLen > MAX_MESSAGE || total > MAX_MESSAGE) throw new Error('message too large');
  if (buf.length < total) return null;

  const whole = buf.subarray(0, total);
  const r = new Reader(whole, le, 16);
  const msg = { type: buf[1], flags: buf[2], serial: rd(8), le, buf: whole, bodyStart };
  while (r.o < headerEnd) {
    r.align(8);
    if (r.o >= headerEnd) break;
    const code = r.u8();
    const sig = r.sig();
    const value = r.value(sig); // a field of an unsupported type makes the message fail, not skip
    if (FIELDS[code]) msg[FIELDS[code][0]] = value;
  }
  return { msg, total };
}

function bodyValues(msg, signature) {
  const r = new Reader(msg.buf, msg.le, msg.bodyStart);
  return [...signature].map((t) => r.value(t));
}

// ---------- the connection ----------

// 'unix:path=/run/user/1000/bus' or 'unix:abstract=...'; entries are separated by ';'
function socketPaths(address) {
  const paths = [];
  for (const entry of String(address || '').split(';')) {
    const m = /^unix:(.*)$/.exec(entry.trim());
    if (!m) continue;
    const kv = {};
    for (const pair of m[1].split(',')) {
      const i = pair.indexOf('=');
      if (i > 0) kv[pair.slice(0, i)] = decodeURIComponent(pair.slice(i + 1));
    }
    if (kv.path) paths.push(kv.path);
    else if (kv.abstract) paths.push(`\0${kv.abstract}`);
  }
  if (!paths.length) {
    const dir = process.env.XDG_RUNTIME_DIR || `/run/user/${process.getuid()}`;
    paths.push(`${dir}/bus`);
  }
  return paths;
}

const DBUS = { destination: 'org.freedesktop.DBus', path: '/org/freedesktop/DBus', iface: 'org.freedesktop.DBus' };

class Bus {
  constructor(socket) {
    this.socket = socket;
    this.buf = Buffer.alloc(0);
    this.serial = 0;
    this.pending = new Map(); // serial -> { resolve, reject, timer, member }
    this.objects = new Map(); // path -> Map(iface -> { Method: { in, out, fn } })
    this.state = 'auth';
    this.closed = false;
    this.unique = null;
    this.onClose = null; // (err) => the connection is gone
  }

  static async connect(address = process.env.DBUS_SESSION_BUS_ADDRESS) {
    let socket = null;
    let lastError = null;
    for (const p of socketPaths(address)) {
      try {
        socket = await new Promise((resolve, reject) => {
          const s = net.connect({ path: p });
          s.once('connect', () => resolve(s));
          s.once('error', reject);
        });
        break;
      } catch (err) {
        lastError = err;
      }
    }
    if (!socket) throw new Error(`no session bus to connect to (${lastError?.message ?? 'no address'})`);
    const bus = new Bus(socket);
    await bus.authenticate();
    [bus.unique] = await bus.call({ ...DBUS, member: 'Hello' });
    return bus;
  }

  authenticate() {
    return new Promise((resolve, reject) => {
      this.authDone = { resolve, reject };
      this.socket.on('data', (chunk) => this.onData(chunk));
      this.socket.on('error', (err) => this.fail(err));
      this.socket.on('close', () => this.fail(new Error('connection closed')));
      const uid = Buffer.from(String(process.getuid())).toString('hex');
      this.socket.write(Buffer.concat([Buffer.from([0]), Buffer.from(`AUTH EXTERNAL ${uid}\r\n`)]));
    });
  }

  fail(err) {
    if (this.closed) return;
    this.closed = true;
    this.authDone?.reject(err);
    this.authDone = null;
    for (const p of this.pending.values()) {
      clearTimeout(p.timer);
      p.reject(err);
    }
    this.pending.clear();
    this.socket.destroy();
    this.onClose?.(err);
  }

  close() {
    this.fail(new Error('closed'));
  }

  next() {
    this.serial = (this.serial % 0xffffffff) + 1;
    return this.serial;
  }

  send(buf) {
    if (!this.closed) this.socket.write(buf);
  }

  onData(chunk) {
    this.buf = this.buf.length ? Buffer.concat([this.buf, chunk]) : chunk;
    if (this.state === 'auth') {
      const i = this.buf.indexOf('\r\n');
      if (i < 0) {
        if (this.buf.length > 4096) this.fail(new Error('auth: no answer'));
        return;
      }
      const line = this.buf.toString('ascii', 0, i);
      this.buf = this.buf.subarray(i + 2);
      if (!line.startsWith('OK')) return this.fail(new Error(`auth refused: ${line.slice(0, 80)}`));
      this.state = 'ready';
      this.socket.write('BEGIN\r\n');
      this.authDone?.resolve();
      this.authDone = null;
    }
    try {
      for (;;) {
        const d = decode(this.buf);
        if (!d) break;
        this.buf = this.buf.subarray(d.total);
        this.onMessage(d.msg);
      }
    } catch (err) {
      this.fail(err);
    }
  }

  onMessage(msg) {
    if (msg.type === TYPE.RETURN || msg.type === TYPE.ERROR) {
      const p = this.pending.get(msg.replySerial);
      if (!p) return;
      this.pending.delete(msg.replySerial);
      clearTimeout(p.timer);
      try {
        const values = bodyValues(msg, msg.signature || '');
        if (msg.type === TYPE.ERROR) p.reject(new Error(`${msg.errorName}: ${values[0] ?? ''}`));
        else p.resolve(values);
      } catch (err) {
        p.reject(err);
      }
    } else if (msg.type === TYPE.CALL) {
      this.handleCall(msg);
    } // signals are ignored
  }

  // args: [['s', 'text'], ['u', 4]]; resolves with the reply's values (basic types only)
  call({ destination, path, iface, member, args = [] }) {
    return new Promise((resolve, reject) => {
      if (this.closed) return reject(new Error('connection closed'));
      try {
        const serial = this.next();
        const body = new Writer();
        for (const [t, v] of args) body.value(t, v);
        const timer = setTimeout(() => {
          this.pending.delete(serial);
          reject(new Error(`${member}: no answer in ${CALL_TIMEOUT_MS} ms`));
        }, CALL_TIMEOUT_MS);
        this.pending.set(serial, { resolve, reject, timer });
        this.send(encode(TYPE.CALL, 0, serial, { path, iface, member, destination, signature: args.map((a) => a[0]).join('') }, body.bytes()));
      } catch (err) {
        reject(err);
      }
    });
  }

  requestName(name, flags = 4) { // 4: DO_NOT_QUEUE; reply 1: you own it
    return this.call({ ...DBUS, member: 'RequestName', args: [['s', name], ['u', flags]] }).then((v) => v[0]);
  }

  getNameOwner(name) {
    return this.call({ ...DBUS, member: 'GetNameOwner', args: [['s', name]] }).then((v) => v[0]);
  }

  // methods: { Name: { in: 's', out: 's', fn: async (args, { sender }) => [values] } }
  export(path, iface, methods) {
    if (!this.objects.has(path)) this.objects.set(path, new Map());
    this.objects.get(path).set(iface, methods);
  }

  introspect(path) {
    const parts = ['<node>'];
    for (const [iface, methods] of this.objects.get(path) || []) {
      parts.push(`<interface name="${iface}">`);
      for (const [name, def] of Object.entries(methods)) {
        parts.push(`<method name="${name}">`);
        for (const t of def.in) parts.push(`<arg type="${t}" direction="in"/>`);
        for (const t of def.out) parts.push(`<arg type="${t}" direction="out"/>`);
        parts.push('</method>');
      }
      parts.push('</interface>');
    }
    parts.push('</node>');
    return parts.join('');
  }

  reply(msg, signature, values) {
    const body = new Writer();
    [...signature].forEach((t, i) => body.value(t, values[i]));
    this.send(encode(TYPE.RETURN, NO_REPLY, this.next(), { replySerial: msg.serial, destination: msg.sender, signature }, body.bytes()));
  }

  fault(msg, errorName, text) {
    const body = new Writer();
    body.str(text);
    this.send(encode(TYPE.ERROR, NO_REPLY, this.next(), { errorName, replySerial: msg.serial, destination: msg.sender, signature: 's' }, body.bytes()));
  }

  async handleCall(msg) {
    const quiet = (msg.flags & NO_REPLY) !== 0;
    try {
      let out;
      if (msg.iface === 'org.freedesktop.DBus.Peer' && msg.member === 'Ping') {
        out = { sig: '', values: [] };
      } else if (msg.iface === 'org.freedesktop.DBus.Introspectable' && msg.member === 'Introspect') {
        out = { sig: 's', values: [this.introspect(msg.path)] };
      } else {
        const def = this.objects.get(msg.path)?.get(msg.iface)?.[msg.member];
        if (!def) throw Object.assign(new Error(`no method ${msg.iface}.${msg.member} at ${msg.path}`), { dbusName: 'org.freedesktop.DBus.Error.UnknownMethod' });
        if ((msg.signature || '') !== def.in) throw Object.assign(new Error(`expected arguments (${def.in})`), { dbusName: 'org.freedesktop.DBus.Error.InvalidArgs' });
        const values = await def.fn(bodyValues(msg, def.in), { sender: msg.sender });
        out = { sig: def.out, values: values || [] };
      }
      if (!quiet) this.reply(msg, out.sig, out.values);
    } catch (err) {
      if (!quiet) this.fault(msg, err.dbusName || 'org.freedesktop.DBus.Error.Failed', String(err.message || err).slice(0, 200));
    }
  }
}

module.exports = { Bus, MAX_MESSAGE };
